/* ---- V550 tables: generated by the builder from EPSON Scan ES00EB HRD --- */
#include "es_hrd_tables.h"
/* UnSharpMask records: max resolution, strength x 10000, radius, clipping */
/* ClipCtl, ClipRev, ClipRevParm pairs */
/* USMNoise row 3 (both tables) and USMBlur */

/* GrainReduction records: max resolution, value (per level) */
static const int kMaxResolution = 6400;     /* V550 optical maximum */

/* Descreening records: max resolution, resolution to scan at, filter value, 3 unused (all 0).
 * HRD types 0..2 are Newspaper, Magazine, Fine Prints; 3 is General. */

/* PMDD::GeneralCmd::GetMoireParam: DescreeningLevel 0 -> table 3, 1 -> 0, 2 -> 1, 3 -> 2 */
int es_descreen_params(int dpi, int ruling, int *scan_dpi, int *value)
{
    const MoireRow *t; size_t n;
    switch (ruling) {
    case 0: t = kMoire3; n = sizeof kMoire3 / sizeof *t; break;
    case 1: t = kMoire0; n = sizeof kMoire0 / sizeof *t; break;
    case 2: t = kMoire1; n = sizeof kMoire1 / sizeof *t; break;
    case 3: t = kMoire2; n = sizeof kMoire2 / sizeof *t; break;
    default: return -1;
    }
    uint32_t prev = 0;
    for (size_t i = 0; i < n; i++) {
        if (prev + 1 <= (uint32_t)dpi && (uint32_t)dpi <= t[i].max_res) {
            *scan_dpi = (int)t[i].scan_res;
            *value = (int)t[i].value;
            return 0;
        }
        prev = t[i].max_res;
    }
    return -1;
}

int es_descreen_max_res(void) { return 600; }

/* Resolution records: requested up to, resolution to scan at (main X, sub Y tables) */
/* HRD tables 0..5 (flatbed colour / gray / B&W: identical on the V550) */
/* HRD tables 18..21 (transparency unit; 18/19 and 20/21 are the same on the V550) */
/* HRD DICE tables 2/3 (DIGITAL ICE) */

static int res_lookup(const ResRow *t, size_t n, int dpi)
{
    uint32_t prev = 0;
    for (size_t i = 0; i < n; i++) {
        if (prev + 1 <= (uint32_t)dpi && (uint32_t)dpi <= t[i].max_res) return t[i].scan_res ? (int)t[i].scan_res : dpi;
        prev = t[i].max_res;
    }
    return -1;
}

/* PMDD::GeneralCmd::GetResolution / GetDICEResolution */
int es_scan_resolution(int film, int ice, int dpi, int *scan_x, int *scan_y)
{
#define N(t) (sizeof t / sizeof *t)
    int x, y;
    if (ice) { x = res_lookup(kResIce, N(kResIce), dpi); y = x; }
    else if (film) { x = res_lookup(kResTpuX, N(kResTpuX), dpi); y = res_lookup(kResTpuY, N(kResTpuY), dpi); }
    else { x = res_lookup(kResFbX, N(kResFbX), dpi); y = res_lookup(kResFbY, N(kResFbY), dpi); }
#undef N
    if (x < 0 || y < 0) return -1;
    *scan_x = x; *scan_y = y;
    return 0;
}

int es_grain_value(int dpi, int level)
{
    if (level < 0 || level > 2) return -1;
    uint32_t prev = 0;
    for (int i = 0; i < 17; i++) {
        if (prev + 1 <= (uint32_t)dpi && (uint32_t)dpi <= kGrain[level][i].max_res) return (int)kGrain[level][i].value;
        prev = kGrain[level][i].max_res;
    }
    return -1;
}

static int map_pair(const char *in_raw, const char *out_raw, size_t size, void **mi, void **mo, int *fi, int *fo)
{
    *fi = open(in_raw, O_RDONLY);
    *fo = open(out_raw, O_RDWR | O_CREAT | O_TRUNC, 0644);
    *mi = *mo = MAP_FAILED;
    if (*fi < 0 || *fo < 0 || ftruncate(*fo, (off_t)size)) return -1;
    *mi = mmap(NULL, size, PROT_READ, MAP_SHARED, *fi, 0);
    *mo = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, *fo, 0);
    return *mi == MAP_FAILED || *mo == MAP_FAILED ? -1 : 0;
}

static void unmap_pair(size_t size, void *mi, void *mo, int fi, int fo)
{
    if (mi != MAP_FAILED) munmap(mi, size);
    if (mo != MAP_FAILED) munmap(mo, size);
    if (fi >= 0) close(fi);
    if (fo >= 0) close(fo);
}

int es_grain_file(const char *engine, const char *in_raw, const char *out_raw, int w, int h, int bits16,
                  int dpi, int grain, char *err, size_t errlen)
{
    size_t rb = (size_t)w * 3 * (bits16 ? 2 : 1), size = rb * (size_t)h;
    void *mi, *mo; int fi, fo, rc = -1;
    if (map_pair(in_raw, out_raw, size, &mi, &mo, &fi, &fo)) snprintf(err, errlen, "can't open temporary files");
    else {
        const int f1[3] = { 0, 0, 0 }, f2[3] = { 0, grain, 0 };
        rc = if_moire(engine, mi, mo, w, h, (int)rb, bits16 ? 48 : 24, dpi, f1, f2, kMaxResolution * 2, err, errlen);
    }
    unmap_pair(size, mi, mo, fi, fo);
    return rc;
}

int es_descreen_file(const char *engine, const char *in_raw, int in_w, int in_h, const char *out_raw,
                     int out_w, int out_h, int spp, int bits16, int dpi, int value, char *err, size_t errlen)
{
    size_t irb = (size_t)in_w * spp * (bits16 ? 2 : 1), orb = (size_t)out_w * spp * (bits16 ? 2 : 1);
    size_t isz = irb * (size_t)in_h, osz = orb * (size_t)out_h;
    int fi = open(in_raw, O_RDONLY), fo = open(out_raw, O_RDWR | O_CREAT | O_TRUNC, 0644), rc = -1;
    void *mi = MAP_FAILED, *mo = MAP_FAILED;
    if (fi >= 0 && fo >= 0 && !ftruncate(fo, (off_t)osz)) {
        mi = mmap(NULL, isz, PROT_READ, MAP_SHARED, fi, 0);
        mo = mmap(NULL, osz, PROT_READ | PROT_WRITE, MAP_SHARED, fo, 0);
    }
    if (mi == MAP_FAILED || mo == MAP_FAILED) snprintf(err, errlen, "can't open temporary files");
    else {
        /* CImgProcessMgr: filter1 = MoireInfo +0x28..+0x30 (0 for the V550), filter2 = the value;
         * the last argument only has to be at least the output resolution (UMOIRE::RemoveMoire) */
        const int f1[3] = { 0, 0, 0 }, f2[3] = { 0, value, 0 };
        rc = if_moire_resize(engine, mi, in_w, in_h, (int)irb, mo, out_w, out_h, (int)orb,
                             spp * (bits16 ? 16 : 8), dpi, f1, f2, es_descreen_max_res(), err, errlen);
    }
    if (mi != MAP_FAILED) munmap(mi, isz);
    if (mo != MAP_FAILED) munmap(mo, osz);
    if (fi >= 0) close(fi);
    if (fo >= 0) close(fo);
    return rc;
}

int es_resize_file(const char *engine, const char *in_raw, int in_w, int in_h, const char *out_raw,
                   int out_w, int out_h, int spp, int bits16, char *err, size_t errlen)
{
    size_t irb = (size_t)in_w * spp * (bits16 ? 2 : 1), orb = (size_t)out_w * spp * (bits16 ? 2 : 1);
    size_t isz = irb * (size_t)in_h, osz = orb * (size_t)out_h;
    int fi = open(in_raw, O_RDONLY), fo = open(out_raw, O_RDWR | O_CREAT | O_TRUNC, 0644), rc = -1;
    void *mi = MAP_FAILED, *mo = MAP_FAILED;
    if (fi >= 0 && fo >= 0 && !ftruncate(fo, (off_t)osz)) {
        mi = mmap(NULL, isz, PROT_READ, MAP_SHARED, fi, 0);
        mo = mmap(NULL, osz, PROT_READ | PROT_WRITE, MAP_SHARED, fo, 0);
    }
    if (mi == MAP_FAILED || mo == MAP_FAILED) snprintf(err, errlen, "can't open temporary files");
    else /* CImgProcessMgr::Initialize: resize mode 1 for 1-bit images, 3 otherwise */
        rc = if_resize(engine, mi, in_w, in_h, (int)irb, mo, out_w, out_h, (int)orb, spp * (bits16 ? 16 : 8), 3,
                       err, errlen);
    if (mi != MAP_FAILED) munmap(mi, isz);
    if (mo != MAP_FAILED) munmap(mo, osz);
    if (fi >= 0) close(fi);
    if (fo >= 0) close(fo);
    return rc;
}

/* PMDD::GeneralCmd::GetUSMParam (Device Control) */
static int usm_lookup(uint32_t res, int level, int film_type, int blc, int *strength, int *radius, int *clipping)
{
    const UsmRow *t; size_t n;
    if (film_type == ES_FILM_NEGA) { t = kUsmTable3; n = sizeof kUsmTable3 / sizeof *t; }
    else if (film_type == ES_FILM_POSI || film_type == ES_FILM_NEGA_BW) { t = kUsmTable4; n = sizeof kUsmTable4 / sizeof *t; }
    else { t = kUsmReflective; n = sizeof kUsmReflective / sizeof *t; }
    size_t i = 0;
    uint32_t prev = 0;
    for (; i < n; i++) {
        if (prev + 1 <= res && res <= t[i].max_res) break;
        prev = t[i].max_res;
    }
    if (i >= n) return -1;
    double s;
    int r, c;
    if (i == 0) {
        r = (int)t[0].radius; s = t[0].strength / 10000.0; c = (int)t[0].clipping;
    } else {
        const UsmRow *p = &t[i - 1];
        if (p->max_res == t[i].max_res) return -1;
        double span = (double)(t[i].max_res - p->max_res), pos = (double)(res - p->max_res);
        r = (int)p->radius + (int)floor((double)((int)(t[i].radius - p->radius) * (int)(res - p->max_res)) / span + 0.5);
        s = pos * (t[i].strength / 10000.0 - p->strength / 10000.0) / span + p->strength / 10000.0;
        c = (int)p->clipping + (int)floor((double)((int)(t[i].clipping - p->clipping) * (int)(res - p->max_res)) / span + 0.5);
    }
    if (r == 0) return -1;
    double k = s * 10.0 / r;
    if (level == 0) k *= 0.7;
    else if (level == 2) k *= 1.4;
    if (blc >= 1 && blc <= 3) k *= 0.8;
    double v = floor(k + 0.5);
    if (v < 0) v = 0;
    int st = (int)v;
    if (st > 500) st = 500;
    *strength = st; *radius = r; *clipping = c;
    return 0;
}

int es_usm_params(int dpi, int level, int film_type, int blc, double screen_gamma,
                  const uint8_t lut[768], IfUsmParams *out)
{
    memset(out, 0, sizeof *out);
    if (usm_lookup((uint32_t)dpi, level, film_type, blc, &out->strength, &out->radius, &out->clipping)) return -1;
    out->flag = 1;
    out->lut = lut;
    out->clip_ctl = kClipCtl;
    out->clip_rev = kClipRev;
    memcpy(out->limits, kClipRevParm, sizeof out->limits);
    /* MakeReviseParmsForLUT */
    uint16_t r[4];
    for (int i = 0; i < 4; i++) r[i] = (uint16_t)(int)(pow(kUsmNoise3[i] / 1000.0, 1.0 / screen_gamma) * 255.0 + 0.5);
    for (int c = 0; c < 3; c++) memcpy(out->revise + 4 * c, r, sizeof r);
    out->revise[12] = kUsmBlur;
    return 0;
}

int es_usm_file(const char *engine, const char *in_raw, const char *out_raw, int w, int h, int bits16,
                const IfUsmParams *p, char *err, size_t errlen)
{
    size_t rb = (size_t)w * 3 * (bits16 ? 2 : 1), size = rb * (size_t)h;
    int fi = open(in_raw, O_RDONLY), fo = open(out_raw, O_RDWR | O_CREAT | O_TRUNC, 0644);
    int rc = -1;
    void *mi = MAP_FAILED, *mo = MAP_FAILED;
    if (fi < 0 || fo < 0 || ftruncate(fo, (off_t)size)) { snprintf(err, errlen, "can't open temporary files"); goto out; }
    mi = mmap(NULL, size, PROT_READ, MAP_SHARED, fi, 0);
    mo = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fo, 0);
    if (mi == MAP_FAILED || mo == MAP_FAILED) { snprintf(err, errlen, "out of memory"); goto out; }
    rc = if_unsharp(engine, mi, mo, w, h, (int)rb, bits16 ? 48 : 24, p, err, errlen);
out:
    if (mi != MAP_FAILED) munmap(mi, size);
    if (mo != MAP_FAILED) munmap(mo, size);
    if (fi >= 0) close(fi);
    if (fo >= 0) close(fo);
    return rc;
}

/* DustRemoval records (per film type, rows = level) */

/* PMDD::GeneralCmd::GetDustRemoveParam + CScanner::PrepareDustRemove */
void es_dust_params(int level, int film_type, int parm[8], int *ddc_type)
{
    int t = film_type == ES_FILM_NEGA || film_type == ES_FILM_NEGA_BW ? 1 : film_type == ES_FILM_POSI ? 2 : 0;
    if (level < 0 || level > 2) level = 1;
    memcpy(parm, kDust[t][level], sizeof kDust[t][level]);
    *ddc_type = film_type == ES_FILM_NONE ? 0 : t;
}

int es_dust_file(const char *engine, const char *prm, const char *raw, int w, int h, int bits16, int dpi,
                 int ddc_type, const int parm[8], char *err, size_t errlen)
{
    size_t rb = (size_t)w * 3 * (bits16 ? 2 : 1), size = rb * (size_t)h;
    int fd = open(raw, O_RDWR), rc = -1;
    void *m = fd >= 0 ? mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0) : MAP_FAILED;
    if (m == MAP_FAILED) snprintf(err, errlen, "can't open the image for Dust Removal");
    else rc = ddc_remove_dust(engine, prm, m, w, h, (int)rb, bits16 ? 48 : 24, dpi, ddc_type, parm, err, errlen);
    if (m != MAP_FAILED) munmap(m, size);
    if (fd >= 0) close(fd);
    return rc;
}
